import{_ as a,C as r,o as n,c as i,j as o,a as d,E as l,a2 as s}from"./chunks/framework.DGvnA5EY.js";const u="/workbuddy-guide/assets/00-hei-intro.B_n5Xquz.png",_=JSON.parse('{"title":"本篇导读 · 第三篇 进阶篇：把案例变成自己的工作系统","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 第二篇的 11 个案例，你跑通任何一个，都会经历同一种感觉：第一次惊喜，第二次顺手， 第三次开始嫌重复——\\"这类活我好像每次都在说同样的话\\"。","frontmatter":{"title":"本篇导读 · 第三篇 进阶篇：把案例变成自己的工作系统"},"headers":[],"relativePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/index.md","filePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/index.md","lastUpdated":1791629861000}'),p={name:"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/index.md"};function q(g,t,h,b,m,c){const e=r("Paywall");return n(),i("div",null,[t[0]||(t[0]=o("h1",{id:"本篇导读-·-第三篇-进阶篇-把案例变成自己的工作系统",tabindex:"-1"},[d("本篇导读 · 第三篇 进阶篇：把案例变成自己的工作系统 "),o("a",{class:"header-anchor",href:"#本篇导读-·-第三篇-进阶篇-把案例变成自己的工作系统","aria-label":'Permalink to "本篇导读 · 第三篇 进阶篇：把案例变成自己的工作系统"'},"​")],-1)),t[1]||(t[1]=o("blockquote",null,[o("p",null,"内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）")],-1)),l(e,{part:"3",variant:"banner"}),t[2]||(t[2]=s('<p>第二篇的 11 个案例，你跑通任何一个，都会经历同一种感觉：<strong>第一次惊喜，第二次顺手， 第三次开始嫌重复</strong>——&quot;这类活我好像每次都在说同样的话&quot;。</p><p>这个&quot;嫌重复&quot;，恰恰是进阶的信号。第三篇要解决的就是它：<strong>把零散的成功，沉淀成 可复用、可协作、可靠的 AI 工作系统</strong>。学完本篇，你手里的不再是&quot;一堆会用的功能&quot;， 而是一台能持续运转的机器。</p><p><img src="'+u+'" alt="一只小黑蹲在地上，把散落的拼图拼成一张完整的图" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解本篇主题，与实际软件界面无关。</em></p><h2 id="本篇的三层结构" tabindex="-1">本篇的三层结构 <a class="header-anchor" href="#本篇的三层结构" aria-label="Permalink to &quot;本篇的三层结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>解决什么</th><th>一句话概括</th></tr></thead><tbody><tr><td>第 22 章 · 打造 Skill</td><td><strong>复用层</strong>：方法论怎么固化</td><td>把书、视频、你自己的经验，蒸馏成一招即来的专属技能</td></tr><tr><td>第 23 章 · 实操案例集</td><td><strong>弹药层</strong>：还有哪些组合可用</td><td>邮件、浏览器自动化、数据分析、多模态……按需取用</td></tr><tr><td>第 24 章 · 多 Agent 设计</td><td><strong>协作层</strong>：一个对话干不动的活怎么办</td><td>把&quot;全能助手&quot;升级成&quot;分工明确的项目团队&quot;</td></tr><tr><td>第 25 章 · 自动化可靠性</td><td><strong>稳定层</strong>：怎么让它每周自己跑不出事</td><td>自动化跑通一次是运气，跑一百次不出事才是系统</td></tr></tbody></table><h2 id="读本篇之前-你该有的基础" tabindex="-1">读本篇之前，你该有的基础 <a class="header-anchor" href="#读本篇之前-你该有的基础" aria-label="Permalink to &quot;读本篇之前，你该有的基础&quot;">​</a></h2><ul><li>第一篇：会用对话、装技能、连 MCP、建自动化（第 1–10 章）；</li><li>第二篇：至少完整跑通过 2–3 个案例，体会过&quot;五问定标 + 选 Skill + 提示词 + 验收&quot; 的完整节奏；</li><li>一个你自己的&quot;重复活清单&quot;：哪些事你每周都在重复？本篇结束时，它就是你的 自动化改造对象。</li></ul><blockquote><p>如果你还没跑过第二篇的案例，建议先回去跑一个。第三篇的所有方法， 都是踩在&quot;真实跑通过一次&quot;的地基上的——没有地基，固化出来的只是空架子。</p></blockquote><h2 id="本篇贯穿的一条主线" tabindex="-1">本篇贯穿的一条主线 <a class="header-anchor" href="#本篇贯穿的一条主线" aria-label="Permalink to &quot;本篇贯穿的一条主线&quot;">​</a></h2><p>和第二篇一样，本篇继续贯彻<strong>零成本思路</strong>：</p><ol><li><strong>先用免费的现成技能跑通</strong>（find-skills 帮你配装）；</li><li><strong>跑顺了的活，用 skill-creator 固化成专属技能</strong>（第 22 章）；</li><li><strong>一个人干不动的，拆成多 Agent 协作</strong>（第 24 章）；</li><li><strong>每周都要干的，交给自动化，并按可靠性清单加固</strong>（第 25 章）。</li></ol><p>四步走完，你就完成了从&quot;用户&quot;到&quot;系统Owner&quot;的转变——这也是第四篇&quot;岗位与行业 落地&quot;的前提：先有自己的系统，才谈得上把它变成职业竞争力。</p><h2 id="本篇任务总清单" tabindex="-1">本篇任务总清单 <a class="header-anchor" href="#本篇任务总清单" aria-label="Permalink to &quot;本篇任务总清单&quot;">​</a></h2><ul><li>[ ] 把至少 1 本书或 1 套视频课蒸馏成 1 个专属 Skill（第 22 章）</li><li>[ ] 从第 23 章案例集中挑 2 个组合，装进自己的工具箱</li><li>[ ] 用多 Agent 架构跑通 1 条内容生产流水线（第 24 章）</li><li>[ ] 把 1 个手动重复活升级为带失败通知的每周自动化（第 25 章）</li><li>[ ] 建立自己的&quot;每周对账&quot;习惯：自动化跑了几次、成功几次、产物在哪</li></ul><hr><p><em>下一篇：第 22 章 打造 Skill——你的经验，值得被固化。</em></p>',17)),l(e,{part:"3"}),t[3]||(t[3]=o("p",null,[o("em",null,"—— 以上试读到此为止。第三篇共 4 章，完整版（飞书文档）包含全部实操内容。——")],-1))])}const f=a(p,[["render",q]]);export{_ as __pageData,f as default};
